mapper.select:
SELECT mm.id, mm.cover_id, mc.cover_no AS cover_code, -- 修正：manhole_cover无name字段，优先用扩展字段ext_common1，无值则关联道路名称 COALESCE(mc.ext_common1, rf.road_name) AS cover_name, sa.id AS area_id, sa.name AS area_name, -- 井盖状态映射（适配实际表字段 + 扩展字段，保留原状态编码逻辑） CASE WHEN mm.tilt_angle > 0 THEN 1 WHEN mm.ext_common1 > 0 THEN 2 -- 位移：用manhole_monitor扩展字段ext_common1替代 WHEN sos.status_code = 'OPEN' THEN 3 -- 开合状态：关联字典表替代is_open字段 WHEN mm.ext_common2 > 0 THEN 4 -- 水淹：用manhole_monitor扩展字段ext_common2替代 WHEN sd.online_status = '离线' THEN 5 -- 设备离线：匹配sys_device的online_status文本值 ELSE 0 END AS cover_status, -- 井盖状态名称（与状态编码一一对应） CASE WHEN mm.tilt_angle > 0 THEN '倾斜' WHEN mm.ext_common1 > 0 THEN '位移' WHEN sos.status_code = 'OPEN' THEN '开启' WHEN mm.ext_common2 > 0 THEN '水淹' WHEN sd.online_status = '离线' THEN '设备离线' ELSE '正常' END AS cover_status_name, -- 🔥 MySQL 类型转换：替换 PG 的 ::TEXT CONCAT(COALESCE(CAST(mm.tilt_angle AS CHAR), '0'), '°') AS tilt_angle, -- 位移：用manhole_monitor扩展字段ext_common1替代 CONCAT(COALESCE(CAST(mm.ext_common1 AS CHAR), '0'), 'cm') AS displacement, -- 水淹水位：用manhole_monitor扩展字段ext_common2替代 CONCAT(COALESCE(CAST(mm.ext_common2 AS CHAR), '0'), 'cm') AS water_level, -- 开合状态：关联sys_open_status字典表获取状态名称（替代原is_open字段） sos.status_name AS is_open, -- 电池电量：用sys_device扩展字段ext_common1替代 COALESCE(sd.ext_common1, '85') AS battery_level, -- 信号强度：用sys_device扩展字段ext_common2替代 COALESCE(sd.ext_common2, '-75dBm') AS signal_strength, -- 🔥 MySQL 时间格式化：替换 PG 的 TO_CHAR DATE_FORMAT(mm.create_time, '%Y-%m-%d %H:%i:%s') AS collect_time, -- 区块链哈希：用manhole_monitor扩展字段ext_common3替代 COALESCE(mm.ext_common3, '0x123abc456def789ghi012jkl345mno678pqr901') AS chain_hash, mm.tenant_id FROM manhole_monitor mm LEFT JOIN manhole_cover mc ON mm.cover_id = mc.id AND mc.deleted = 0 LEFT JOIN road_facility rf ON mc.road_id = rf.id AND rf.deleted = 0 -- 关联道路表获取井盖所属名称 LEFT JOIN sys_area sa ON mc.area_code = sa.full_code AND sa.deleted = 0 LEFT JOIN sys_device sd ON mm.device_id = sd.id AND sd.deleted = 0 LEFT JOIN sys_open_status sos ON mm.open_status_id = sos.id -- 关联开合状态字典表 WHERE mm.deleted = 0 AND mm.tenant_id = #{reqVO.tenantId}
AND mm.cover_id = #{reqVO.coverId}
AND sa.id = #{reqVO.areaId}
AND CASE WHEN mm.tilt_angle > 0 THEN 1 WHEN mm.ext_common1 > 0 THEN 2 WHEN sos.status_code = 'OPEN' THEN 3 WHEN mm.ext_common2 > 0 THEN 4 WHEN sd.online_status = '离线' THEN 5 ELSE 0 END = #{reqVO.coverStatus}
AND mm.create_time >= #{reqVO.monitorTimeStart}
AND mm.create_time <= #{reqVO.monitorTimeEnd}
ORDER BY mm.create_time DESC

mapper.update:
UPDATE sys_device SET online_status = #{onlineStatus}, update_time = NOW(), updater = 1 WHERE id IN ( SELECT device_id FROM manhole_monitor WHERE cover_id IN
#{coverId}
)

mapper.select:
SELECT COALESCE(sw.warn_no, '无预警编号') AS warn_no, COALESCE(mc.cover_no, '无井盖编号') AS cover_no, COALESCE(rf.road_name, '无路段名称') AS road_name, COALESCE(do1.abnormal_type, '无异常类型') AS abnormal_type, COALESCE(sos.status_name, '无开合状态') AS open_status_name, COALESCE(mm.tilt_angle, 0.00) AS tilt_angle, COALESCE(mm.vibration_data, 0.00) AS vibration_data, sw.create_time, COALESCE(sw.deal_limit, 0.0) AS deal_limit, -- 🔥 MySQL 替换 PG 时间计算函数 COALESCE(ROUND((sw.deal_limit - TIMESTAMPDIFF(SECOND, sw.create_time, NOW()) / 3600), 1), 0.0) AS remaining_time, COALESCE(sw.assign_status, '无派单状态') AS assign_status, COALESCE(srl.level_name, '无风险等级') AS level_name, COALESCE(sw.suggest, '无处置建议') AS suggest FROM sys_warn sw LEFT JOIN disposal_order do1 ON sw.id = do1.warn_id AND do1.deleted = 0 AND do1.tenant_id = 1 LEFT JOIN manhole_cover mc ON sw.facility_id = mc.id AND mc.deleted = 0 AND mc.tenant_id = 1 LEFT JOIN road_facility rf ON mc.road_id = rf.id AND rf.deleted = 0 AND rf.tenant_id = 1 LEFT JOIN manhole_monitor mm ON mc.id = mm.cover_id AND mm.deleted = 0 AND mm.tenant_id = 1 LEFT JOIN sys_open_status sos ON mm.open_status_id = sos.id LEFT JOIN sys_risk_level srl ON do1.risk_level_id = srl.id WHERE sw.deleted = 0 AND sw.facility_type = '窨井盖' AND sw.tenant_id = 1
AND rf.road_name LIKE CONCAT('%', #{reqVO.roadName}, '%')
AND mc.cover_no LIKE CONCAT('%', #{reqVO.coverNo}, '%')
AND do1.abnormal_type = #{reqVO.abnormalType}
AND srl.level_name = #{reqVO.riskLevel}
ORDER BY sw.create_time DESC
LIMIT #{reqVO.pageSize} OFFSET #{reqVO.offset}

SELECT COUNT(1) FROM sys_warn sw LEFT JOIN disposal_order do1 ON sw.id = do1.warn_id AND do1.deleted = 0 AND do1.tenant_id = 1 LEFT JOIN manhole_cover mc ON sw.facility_id = mc.id AND mc.deleted = 0 AND mc.tenant_id = 1 LEFT JOIN road_facility rf ON mc.road_id = rf.id AND rf.deleted = 0 AND rf.tenant_id = 1 LEFT JOIN manhole_monitor mm ON mc.id = mm.cover_id AND mm.deleted = 0 AND mm.tenant_id = 1 LEFT JOIN sys_open_status sos ON mm.open_status_id = sos.id LEFT JOIN sys_risk_level srl ON do1.risk_level_id = srl.id WHERE sw.deleted = 0 AND sw.facility_type = '窨井盖' AND sw.tenant_id = 1
AND rf.road_name LIKE CONCAT('%', #{reqVO.roadName}, '%')
AND mc.cover_no LIKE CONCAT('%', #{reqVO.coverNo}, '%')
AND do1.abnormal_type = #{reqVO.abnormalType}
AND srl.level_name = #{reqVO.riskLevel}
